create temporary view   bought_data_${grass_region_without_quote}
as
select  user_id
        ,item_id
        ,event_timestamp
        ,log_timestamp
        ,ROW_NUMBER() OVER (PARTITION BY item_id
        ORDER BY event_timestamp DESC, log_timestamp DESC, user_id) AS row_num
from    (
    select  user_id
            ,item_id
            ,max(event_timestamp) as event_timestamp
            ,max(log_timestamp) as log_timestamp
    from    srdi_mart.dwd_sr_data_warehouse_platform
    where   local_date BETWEEN date_sub(${local_date}, 2)
      and   ${local_date}
      and   grass_region = ${grass_region}
      and   operation = 'order'
      and   source1_page_type = 'home'
      and   source1_page_section[0] = 'daily_discover'
      and   source1_target_type = 'item_mix_feed_card'
      and   COALESCE(user_id, 0) > 0
    group by 1, 2
)
;
